import manifest from 'virtual:playhub-assets';

/**
 * Which files exist in /public. The list is generated by vite.config.js, so the
 * app never requests a model or sound that isn't there (no 404 noise), and
 * dropping a new file into public/ is picked up automatically in dev.
 */
const files = new Set(manifest);

const isLocal = (url) => typeof url === 'string' && url.startsWith('/') && !url.startsWith('//');

/** Synchronous check for files in /public. Remote URLs count as present. */
export function hasAsset(url) {
  if (!url) return false;
  if (!isLocal(url)) return true;
  return files.has(decodeURI(url.split('?')[0]));
}

/** Async check: uses the manifest for local files, a HEAD request for remote ones. */
export async function assetExists(url) {
  if (!url) return false;
  if (isLocal(url)) return hasAsset(url);
  try {
    const res = await fetch(url, { method: 'HEAD' });
    return res.ok && !String(res.headers.get('content-type')).includes('text/html');
  } catch {
    return false;
  }
}
